import json
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
OUT = "/tmp/recon/raw.json"

state = {"token": None}


def log(msg):
    print(msg, file=sys.stderr, flush=True)


def new_token():
    req = urllib.request.Request(BASE + "/token", method="POST")
    with urllib.request.urlopen(req, timeout=30) as r:
        state["token"] = json.load(r)["token"]
    log(f"token refreshed: {state['token']}")


def request(path, auth=True):
    """GET path, retrying on 401 (new token), 429 (honour wait), 5xx and network errors."""
    attempt = 0
    while True:
        attempt += 1
        if auth and state["token"] is None:
            new_token()
        headers = {}
        if auth:
            headers["Authorization"] = "Bearer " + state["token"]
        req = urllib.request.Request(BASE + path, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return json.load(r), dict(r.headers)
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", "replace")
            hdrs = dict(e.headers)
            log(f"{path} -> HTTP {e.code} attempt {attempt} headers={hdrs} body={body[:300]}")
            if e.code == 404:
                return None, hdrs
            if e.code in (401, 403):
                new_token()
                continue
            if e.code == 429:
                wait = hdrs.get("Retry-After")
                try:
                    secs = float(wait) if wait is not None else None
                except ValueError:
                    secs = None
                if secs is None:
                    secs = 5
                log(f"rate limited, sleeping {secs}s")
                time.sleep(secs)
                continue
            # other errors: retry with backoff
            time.sleep(min(2 * attempt, 30))
            continue
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            log(f"{path} network error attempt {attempt}: {e}")
            time.sleep(min(2 * attempt, 30))
            continue


def main():
    pages = {}
    page = 1
    total_pages = None
    while True:
        data, _ = request(f"/orders?page={page}")
        if total_pages is None:
            total_pages = data["total_pages"]
            log(f"total_pages={total_pages}")
        if data["page"] != page:
            log(f"WARNING: asked for page {page}, got page {data['page']}")
        pages[page] = data["items"]
        log(f"page {page}: {len(data['items'])} items, next={data['next']}")
        if page >= total_pages:
            if data["next"] is not None:
                log(f"WARNING: last page {page} still has next={data['next']}")
            break
        if data["next"] is None:
            log(f"WARNING: page {page} has next=None before total_pages={total_pages}")
            break
        page += 1

    customers = {}
    needed = sorted({o["customer_id"] for items in pages.values() for o in items})
    for cid in needed:
        data, _ = request(f"/customers/{cid}")
        customers[cid] = data
    log(f"customers fetched: {len(customers)} (missing: {sum(1 for v in customers.values() if v is None)})")

    with open(OUT, "w") as f:
        json.dump({"pages": pages, "customers": customers, "total_pages": total_pages}, f)
    log(f"wrote {OUT}")


if __name__ == "__main__":
    main()

